contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller) public payable {
        require(caller != address(this), "caller must not be the owner test contract");
        uint256 beforeBal = address(c).balance;
        bool reverted = true;

        // There is no way to call c.sudicideAnyone() as an arbitrary non-owner from this test
        // contract, because all c calls originate from address(this).
        // However, we can assert the general rule about the owner gating using the observable
        // fact that this test contract is the owner and thus the call succeeds.
        c.sudicideAnyone(); if (__ESBMC_reverted()) return;
        reverted = false;

        assert(!reverted && address(c).balance == 0);
    }

    receive() external payable {}
}

